@import "@fontsource-variable/inter";
@import "@fontsource-variable/source-code-pro";

/* Light (sibling): warm paper, black ink, the same hairline logic and inverted black button. */
:root {
  --background: oklch(0.975 0.003 90);
  --foreground: oklch(0.16 0 0);
  --card: oklch(0.955 0.003 90);
  --card-foreground: oklch(0.16 0 0);
  --popover: oklch(0.985 0.002 90);
  --popover-foreground: oklch(0.16 0 0);
  --primary: oklch(0.16 0 0);
  --primary-foreground: oklch(0.985 0.002 90);
  --secondary: oklch(0.93 0.004 90);
  --secondary-foreground: oklch(0.16 0 0);
  --muted: oklch(0.88 0.012 250);
  --muted-foreground: oklch(0.45 0 0);
  --accent: oklch(0.93 0.004 90);
  --accent-foreground: oklch(0.16 0 0);
  --destructive: oklch(0.55 0.2 27);
  --destructive-foreground: oklch(0.985 0.002 90);
  --border: oklch(0.16 0 0 / 12%);
  --input: oklch(0.16 0 0 / 22%);
  --ring: oklch(0.16 0 0 / 60%);
  --highlight: oklch(0.45 0.03 250);
  --highlight-foreground: oklch(0.985 0.002 90);
  --glow: oklch(0.72 0.035 250);
  --chart-1: oklch(0.16 0 0);
  --chart-2: oklch(0.45 0.03 250);
  --chart-3: oklch(0.6 0.02 250);
  --chart-4: oklch(0.75 0.015 250);
  --chart-5: oklch(0.88 0.012 250);
  --sidebar: oklch(0.955 0.003 90);
  --sidebar-foreground: oklch(0.16 0 0);
  --sidebar-primary: oklch(0.16 0 0);
  --sidebar-primary-foreground: oklch(0.985 0.002 90);
  --sidebar-accent: oklch(0.93 0.004 90);
  --sidebar-accent-foreground: oklch(0.16 0 0);
  --sidebar-border: oklch(0.16 0 0 / 12%);
  --sidebar-ring: oklch(0.16 0 0 / 60%);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Source Code Pro Variable", ui-monospace, SFMono-Regular, Menlo, monospace;
  --radius: 0rem;
  --page-width: 120rem;
  --page-gutter: 1rem;
  --section-y: 6rem;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 2rem;
    --section-y: 6.5rem;
  }
}

/* Dark (faithful): pure black, white ink, white 10% hairlines, blue-grey liquid glow. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.09 0 0);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.12 0 0);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(1 0 0);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.16 0 0);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.2 0.014 250);
  --muted-foreground: oklch(1 0 0 / 58%);
  --accent: oklch(1 0 0 / 6%);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.65 0.2 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 20%);
  --ring: oklch(1 0 0 / 60%);
  --highlight: oklch(0.62 0.03 250);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.45 0.035 250);
  --chart-1: oklch(1 0 0);
  --chart-2: oklch(0.62 0.03 250);
  --chart-3: oklch(0.45 0.035 250);
  --chart-4: oklch(0.32 0.02 250);
  --chart-5: oklch(0.2 0.014 250);
  --sidebar: oklch(0.09 0 0);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(1 0 0);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.16 0 0);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(1 0 0 / 60%);
}
